bool hosts(){CHECK(host_allowed("192.168.1.83",0xc0a80153));CHECK(host_allowed("192.168.1.83:80",0xc0a80153));for(auto h:{"evil.test","192.168.4.1","192.168.1.83:81","192.168.1.83.evil","192.168.1.83@evil","192.168.1.83\r\n"})CHECK(!host_allowed(h,0xc0a80153));return true;}
bool cursors(){U64 v;CHECK(cursor("0",v)&&v==0);CHECK(cursor("18446744073709551615",v)&&v==~U64(0));for(auto s:{"","-1","18446744073709551616","1&x=1","1.0","a"})CHECK(!cursor(s,v));return true;}
bool reboot_policy(){Reboot r;CHECK(r.request(100,true,false)==Reboot::Result::REFUSE);CHECK(!r.pending);CHECK(r.request(100,false,true)==Reboot::Result::REFUSE);CHECK(r.request(100,false,false)==Reboot::Result::ACCEPT);CHECK(r.request(200,false,false)==Reboot::Result::COALESCE);CHECK(r.due==600);CHECK(!r.execute(599,false,false));CHECK(r.execute(600,false,false));CHECK(!r.execute(601,false,false));CHECK(r.request(1000,false,false)==Reboot::Result::ACCEPT);CHECK(!r.execute(2000,true,false)&&!r.pending);CHECK(r.request(2100,false,false)==Reboot::Result::ACCEPT);CHECK(!r.execute(3000,false,true)&&!r.pending);return true;}
bool json_bounds(){Snapshots s{};s.core.time=s.power.time=s.network.time=100;s.core.values.fill(100);s.core.control_values.fill(100);s.core.input_values.fill(7);s.core.rtcp.set_stage_failure(12,6);s.core.rtcp.error=-7;s.core.rtcp.server_hello_bytes=56;s.core.rtcp.close_reason=7;s.core.rtcp.close_count=9;s.core.rtcp.last_poll_32ms=2;s.core.rtcp.max_poll_32ms=95;s.core.rtcp.timeout_elapsed_32ms=96;s.core.rtcp.timeout_state=6;s.core.rtcp.timeout_queued_bytes=27;s.core.rtcp.timeout_unread_count=4;s.core.rtcp.counters.fill(9);s.power.values.fill(100);s.network.values.fill(1);s.network.rssi=-61;s.network.http_dns_off=true;std::strcpy(s.network.ip,"192.168.1.83");std::strcpy(s.network.ssid,"<x>\"\\\n");char out[response_bytes]{};
 CHECK(status_json(s,1000,"REMOTE","1","abc",3,out,sizeof out));CHECK(std::strstr(out,"\"age_ms\":900"));CHECK(std::strstr(out,"\\u003c"));CHECK(!std::strstr(out,"<x>"));CHECK(std::strstr(out,"\"rssi\":-61"));CHECK(std::strstr(out,"\"http_dns_off\":1"));CHECK(std::strstr(out,"\"rtcp_stage\":12"));CHECK(std::strstr(out,"\"rtcp_failure\":6"));CHECK(std::strstr(out,"\"rtcp_error\":-7"));CHECK(std::strstr(out,"\"rtcp_server_hello_bytes\":56"));CHECK(std::strstr(out,"\"rtcp_close_reason\":7"));CHECK(std::strstr(out,"\"rtcp_close_count\":9"));CHECK(std::strstr(out,"\"rtcp_poll_last_ms\":64"));CHECK(std::strstr(out,"\"rtcp_poll_max_ms\":3040"));CHECK(std::strstr(out,"\"rtcp_timeout_state\":6"));CHECK(std::strstr(out,"\"rtcp_timeout_elapsed_ms\":3072"));CHECK(std::strstr(out,"\"rtcp_timeout_queued_bytes\":27"));CHECK(std::strstr(out,"\"rtcp_timeouts_with_unread\":4"));CHECK(std::strstr(out,"\"rtcp_identity_accepted\":9"));CHECK(!std::strstr(out,"password"));CHECK(!std::strstr(out,"token"));CHECK(std::strstr(out,"ENABLED"));
 struct Guard {char a='A';char data[16]{};char b='B';} g;CHECK(!status_json(s,1,"R","V","S",1,g.data,sizeof g.data));CHECK(g.a=='A'&&g.b=='B');CHECK(!status_json(s,1,"R","V","S",1,g.data,0));
 s={};CHECK(status_json(s,1,"R","V","S",1,out,sizeof out));CHECK(std::strstr(out,"\"available\":0"));
 s.core.time=s.power.time=s.network.time=UINT64_MAX;s.core.values.fill(UINT64_MAX);s.core.control_values.fill(UINT32_MAX);s.core.input_values.fill(UINT16_MAX);s.core.rtcp.counters.fill(UINT8_MAX);s.core.browser.counters.fill(UINT16_MAX);s.power.values.fill(UINT64_MAX);s.network.values.fill(UINT64_MAX);std::memset(s.power.resets,0xff,sizeof s.power.resets);std::strcpy(s.network.ip,"255.255.255.255");std::memset(s.network.ssid,'&',32);s.network.ssid[32]=0;s.network.rssi=-128;
 CHECK(status_json(s,UINT64_MAX,"REMOTE-01-LONG","1234567890123456789012345678901","ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff",UINT32_MAX,out,sizeof out));CHECK(std::strlen(out)<sizeof out);return true;}
bool reset_copy(){using namespace power_management;reset_diagnostic::History h{};auto r=reset_diagnostic::begin(h,5,0);r.w[reset_diagnostic::MV]=4155;reset_diagnostic::save(h,r);auto i=reset_diagnostic::latest(h);auto row=sanitize_reset_record(h.copies[i/2][i%2]);CHECK(row.available&&row.values[1]==5&&row.values[7]==4155);row.values[7]=0;CHECK(h.copies[i/2][i%2].w[reset_diagnostic::MV]==4155);auto bad=h.copies[i/2][i%2];bad.w[reset_diagnostic::MV]++;CHECK(!sanitize_reset_record(bad).available);bad={};CHECK(!sanitize_reset_record(bad).available);CHECK(sizeof(reset_diagnostic::History)==640);CHECK(sizeof(ResetSummary)==256);return true;}
bool route_policy(){CHECK(route("/",true,0)==Route::HOME);CHECK(route("/api/status",true,0)==Route::STATUS);CHECK(route("/api/rtcp-history",true,0)==Route::RTCP_HISTORY);CHECK(route("/api/events?after=12",true,0)==Route::EVENTS);for(auto uri:{"/credentials","/reboot","/api/status?secret=x","/api/events?after=-1","/api/events?after=1&other=x","/ota"})CHECK(route(uri,true,0)==Route::DENY);CHECK(route("/",false,0)==Route::DENY);CHECK(route("/",true,1)==Route::DENY);Address a{1,0xffffff00,1,true},b=a;CHECK(a==b);b.generation++;CHECK(!(a==b));b=a;b.ip++;CHECK(!(a==b));return true;}
bool command_path(){network_manager::Inbox inbox;network_manager::Message m{};m.kind=network_manager::Kind::REBOOT;CHECK(inbox.post(m));m={};CHECK(inbox.pop(m)&&m.kind==network_manager::Kind::REBOOT);CHECK(!inbox.pop(m));CHECK(sizeof(RtcpDiagnostic)==24);CHECK(sizeof(BrowserDiagnostic)==16);CHECK(sizeof(Snapshots)==1024);CHECK(sizeof(Entry)==24);CHECK(sizeof(RtcpCloseHistory)==136);CHECK(sizeof(Snapshots)+sizeof(Ring)+sizeof(RtcpCloseHistory)+response_bytes==8192);BrowserDiagnostic b{};b.counters[0]=UINT16_MAX;BrowserDiagnostic::increment(b.counters[0]);CHECK(b.counters[0]==UINT16_MAX);return true;}
bool ring_stress(unsigned cycles){Ring r;Reboot reboot;for(unsigned i=0;i<cycles;++i){r.push(i,Event::NETWORK,i);CHECK(r.next==U64(i)+2);CHECK(r.slots[i%32].sequence==U64(i)+1);CHECK(r.overflow==(i<32?0:i-31));CHECK(r.oldest()==(i<32?1:i-30));Address a{0xc0a80153,0xffffff00,i,true};CHECK(socket_allowed(a,a.ip,0xc0a80102));a.ready=false;CHECK(!socket_allowed(a,a.ip,0xc0a80102));CHECK(reboot.request(U64(i)*1000,false,false)==Reboot::Result::ACCEPT);CHECK(!reboot.execute(U64(i)*1000+499,false,false));CHECK(reboot.execute(U64(i)*1000+500,false,false));}return true;}
int main(int argc,char**argv){unsigned cycles=argc>1&&std::string(argv[1])=="--soak"?10000:1000;unsigned pass=0;for(auto fn:{addresses,hosts,cursors,reboot_policy,json_bounds,reset_copy,route_policy,command_path}){if(!fn())return 1;++pass;}if(!ring_stress(cycles))return 1;++pass;std::printf("DIAGNOSTICS: PASS=%u FAIL=0 assertions=%u cycles=%u\n",pass,assertions,cycles);}
